ctx, cancel := context.WithTimeout(context.Background(), 12*time.Second)
defer cancel()
stream, err := client.StreamResponses(ctx, &StreamParams{Model: 'short-v2', Input: 'Summarize'})
if err != nil { log.Fatalf('start: %v', err) }
for {
    msg, err := stream.Recv()
    if err == io.EOF { break }
    if err != nil { log.Printf('recv err: %v', err); break }
    if msg.Type == DeltaMessage { fmt.Print(msg.Delta.Text) }
}
stream.Close()
```

